#[path = "../src/bin/implementation_inventory/equals_witness.rs"]
mod witness;
use digimon_dsl::{CardSpec,compiled::*,compile::compile};
use witness::{witness_equals_if,IfLocation,Branch};
fn raw(cond:&str)->Vec<u8>{format!("card: TEST-01\nname: Test\nkind: digimon\nlevel: 3\ncolor: [red]\ncost: 2\ndp: 3000\neffects:\n  - when: on_play\n    process:\n      - if:\n          condition: {cond}\n          then: [{{gain_memory: 1}}]\n").into_bytes()}
fn c(r:&[u8])->CompiledCard{compile(&serde_yml::from_slice::<CardSpec>(r).unwrap()).unwrap()}
fn loc()->IfLocation{IfLocation{effect:0,ancestors:vec![],step:0}}
#[test]fn unrelated_compiled_metadata_drift_is_refused(){let r=raw("{equals: [slot, 0]}");let mut supplied=c(&r);supplied.name="Changed".into();assert!(witness_equals_if(&r,"TEST-01",&loc(),&supplied).is_err());}
#[test]fn byte_identity_not_inferred_from_equal_compilation(){let r=raw("{equals: [slot, 0]}");let mut other=r.clone();other.extend_from_slice(b"# distinct original bytes\n");let supplied=c(&r);let w=witness_equals_if(&other,"TEST-01",&loc(),&supplied).unwrap();assert_eq!(w.original_source_bytes,other);assert_ne!(w.original_source_bytes,r);}
#[test]fn strict_floating_and_out_of_range_numeric_refusal(){for v in ["0.0","-0.0",".nan",".inf","9223372036854775808","-9223372036854775809"]{let r=raw(&format!("{{equals: [slot, {v}]}}"));if let Ok(s)=serde_yml::from_slice::<CardSpec>(&r){if let Ok(compiled)=compile(&s){assert!(witness_equals_if(&r,"TEST-01",&loc(),&compiled).is_err(),"{v}");}}}}
#[test]fn nested_then_else_locations_do_not_alias(){let r=b"card: TEST-01\nname: Test\nkind: digimon\nlevel: 3\ncolor: [red]\ncost: 2\ndp: 3000\neffects:\n  - when: on_play\n    process:\n      - if:\n          condition: {binding_present: outer}\n          then:\n            - if:\n                condition: {equals: [same, 0]}\n                then: [{gain_memory: 1}]\n          else:\n            - if:\n                condition: {equals: [same, 0]}\n                then: [{gain_memory: 2}]\n";let compiled=c(r);let a=witness_equals_if(r,"TEST-01",&IfLocation{ancestors:vec![(0,Branch::Then)],..loc()},&compiled).unwrap();let b=witness_equals_if(r,"TEST-01",&IfLocation{ancestors:vec![(0,Branch::Else)],..loc()},&compiled).unwrap();assert_ne!(a.original_opaque_paths,b.original_opaque_paths);assert_ne!(a.compiled_operand_paths,b.compiled_operand_paths);assert!(a.original_opaque_paths[0].contains(".then[0]"));assert!(b.original_opaque_paths[0].contains(".else_[0]"));}
#[test]fn sibling_typed_predicate_is_not_silently_discarded(){let r=raw("{equals: [slot, 0], binding_absent: other}");if let Ok(s)=serde_yml::from_slice::<CardSpec>(&r){if let Ok(compiled)=compile(&s){assert!(witness_equals_if(&r,"TEST-01",&loc(),&compiled).is_err());}}}
